package net.civeira.phylax.features.document.theme.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.features.document.theme.application.visibility.ThemeFixedPropertiesProposal;

public class FixTenantExcludingRoot {

  /**
   * @autogenerated VisibilityPolicyGenerator
   * @param fixed
   */
  public void fixedFields(@Observes ThemeFixedPropertiesProposal fixed) {
    Actor actor = fixed.getActor();
    if (!(actor.hasScope("platform:global_access"))) {
      fixed.add("tenant");
    }
  }
}
